// Game.js

class Game {
  constructor() {
    this.score = 0;
    this.level = 1;
    this.level_complete = false;
    this.level_complete_message = 'Level Complete';
  }

  update() {
    if (this.level_complete) {
      this.level++;
      this.level_complete_message = 'Level Complete';
    } else {
      this.level_complete = true;
    }
  }

  render() {
    // Draw the game board
    ctx.fillStyle = 'white';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // Draw the player
    ctx.fillStyle = 'red';
    ctx.fillRect(player.x, player.y, 10, 10);

    // Draw the score
    ctx.fillStyle = 'green';
    ctx.fillText(this.score, 10, 10);
  }
}

// Game.js

const canvas = document.querySelector('canvas');
const ctx = canvas.getContext('2d');

const game = new Game();

// Game loop

setInterval(() => {
  game.update();
  game.render();
